; DAPP.S - APPLICATIONS PAGE RENDERER
;
; QUERIES DOS_GET_APP_INFO ($5D) ONCE PER SLOT (0..15) PER APPLICATIONS-PAGE
; REDRAW AND RENDERS EACH OCCUPIED SLOT AS ONE BOUNDED ROW: NAME, INCLUSIVE
; RANGE, SIZE, AND U/R/V/S FLAGS. NEVER READS PRIVATE APP-TABLE/VMM STATE
; DIRECTLY -- ALL DATA COMES FROM THE PUBLIC $5D RECORD.
;
; ROW GEOMETRY (FROZEN): ROW 4 = COLUMN HEADER, ROWS 5-20 = SLOTS 0-15 (ONE
; ROW PER SLOT, FIXED BY SLOT INDEX, NOT BY OCCUPANCY ORDER). NO SEPARATE
; PAGE-TITLE ROW -- THE ROW-2 TAB BAR ALREADY IDENTIFIES THIS PAGE, AND ROW 4
; IS NEEDED TO FIT EXACTLY 1 HEADER + 16 DATA ROWS IN THE 17-ROW CONTENT
; FRAME (ROWS 4-20).
;
; COLUMNS (FROM COL 2): NAME 2-16 (15 WIDE, THE FULL WP1 NAME LENGTH -- NEVER
; TRUNCATED), SPACE 17, RANGE 18-26 ("LLLL-EEEE", 9 WIDE), SPACE 27,
; SIZE 28-31 (4 HEX DIGITS), SPACE 32, FLAGS 33-36 (4 CHARS).
;
; RUNNING FLAG (R): APT_FLAG_RUNNING IS NEVER SET BY ANY CODE PATH TODAY (NO
; LOADER SETS IT ON LAUNCH; DOS_EXIT DOES NOT CLEAR IT) -- TRACKED AS TASK
; WARRIOR #42. THE BIT IS THEREFORE TRUTHFULLY '-' FOR EVERY APP RIGHT NOW.
; THIS PAGE RENDERS THE RAW BIT AS-IS (NEVER INFERRING RUNNING STATE ANY
; OTHER WAY) BUT IMPLEMENTS NO ROW HIGHLIGHT, SINCE THERE IS NO TRUTHFUL
; "RUNNING" CASE TO HIGHLIGHT YET.

; DAPPRENDER - TOP-LEVEL APPLICATIONS-PAGE REDRAW ENTRY POINT.
; INPUT: NONE. OUTPUT: NONE. CLOBBERS: A, X, Y.
DAPPRENDER:
    JSR CLEARSCREEN
    JSR DRAWFRAME
    JSR DAPPHEADER

    LDA #0
    STA APPCURSLOT
    LDA #0
    STA APPOCCCOUNT

@LOOP:
    LDA APPCURSLOT
    CMP #APP_MAX_SLOTS
    BCS @LOOPDONE

    STA $66                     ; HEXVALLO = REQUESTED SLOT INDEX (0..15)
    LDX #<APPBUF
    LDY #>APPBUF
    LDA #DOS_GET_APP_INFO
    JSR OS_API
    BCS @CHECKFAIL

    ; OCCUPIED: VALIDATE STRUCTVERSION (OFFSET 0) == 1 AND STRUCTSIZE
    ; (OFFSET 1) == 24 BEFORE TRUSTING ANY FIELD.
    LDA APPBUF+APP_OFF_STRUCTVERSION
    CMP #APP_STRUCT_VERSION
    BNE @QUERYERR
    LDA APPBUF+APP_OFF_STRUCTSIZE
    CMP #APP_STRUCT_SIZE
    BNE @QUERYERR

    JSR DAPPRENDERROW
    INC APPOCCCOUNT
    JMP @NEXTSLOT

@CHECKFAIL:
    CMP #DOS_ERR_SLOT_EMPTY
    BEQ @NEXTSLOT            ; EMPTY IS NOT A PAGE ERROR: SKIP SILENTLY
    JMP @QUERYERR            ; INVALID/UNAVAILABLE/MALFORMED: STOP

@NEXTSLOT:
    INC APPCURSLOT
    JMP @LOOP

@LOOPDONE:
    LDA APPOCCCOUNT
    BNE @DONE

    LDA #COL_CONTENT
    LDY #ROW_APP_SLOT0
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<APPNOAPPSSTR
    LDY #>APPNOAPPSSTR
    JSR SCREENPUTSTRING

@DONE:
    RTS

; @QUERYERR - BOUNDED PAGE-WIDE FAILURE. PRINTED ON THE CURRENT SLOT'S OWN
; ROW (ALWAYS 5-20, SINCE APPCURSLOT IS ALWAYS 0-15 HERE), SO IT NEVER
; OVERWRITES THE FRAME OR ANOTHER SLOT'S ROW. ENUMERATION STOPS -- NO FURTHER
; SLOTS ARE QUERIED.
@QUERYERR:
    LDA APPCURSLOT
    CLC
    ADC #ROW_APP_SLOT0
    TAY
    LDA #COL_CONTENT
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<APPERRSTR
    LDY #>APPERRSTR
    JSR SCREENPUTSTRING
    RTS

; DAPPHEADER - PRINTS THE COLUMN HEADER ON ROW 4.
; CLOBBERS: A, X, Y.
DAPPHEADER:
    LDA #COL_CONTENT
    LDY #ROW_APP_HEADER
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<APPHDR_NAME
    LDY #>APPHDR_NAME
    JSR SCREENPUTSTRING

    LDA #COL_APP_RANGE
    LDY #ROW_APP_HEADER
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<APPHDR_RANGE
    LDY #>APPHDR_RANGE
    JSR SCREENPUTSTRING

    LDA #COL_APP_SIZE
    LDY #ROW_APP_HEADER
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<APPHDR_SIZE
    LDY #>APPHDR_SIZE
    JSR SCREENPUTSTRING

    LDA #COL_APP_FLAGS
    LDY #ROW_APP_HEADER
    JSR SCREENSETCURSOR
    LDA #SCREEN_COLS
    LDX #<APPHDR_FLAGS
    LDY #>APPHDR_FLAGS
    JSR SCREENPUTSTRING
    RTS

; DAPPRENDERROW - RENDERS ONE OCCUPIED-SLOT ROW FROM APPBUF AT ROW
; (5 + APPCURSLOT), COLUMN 2.
; INPUT: APPCURSLOT = SLOT INDEX (0-15). APPBUF = FRESH RECORD FOR THAT SLOT.
; CLOBBERS: A, X, Y.
DAPPRENDERROW:
    LDA APPCURSLOT
    CLC
    ADC #ROW_APP_SLOT0
    TAY
    LDA #COL_CONTENT
    JSR SCREENSETCURSOR

    JSR DAPPPRINTNAME

    LDA #SCREENCODE_SPACE
    JSR SCREENPUTCHAR

    JSR DAPPPRINTRANGE

    LDA #SCREENCODE_SPACE
    JSR SCREENPUTCHAR

    LDX APPBUF+APP_OFF_SIZE                ; SIZE LO
    LDY APPBUF+APP_OFF_SIZE+1                ; SIZE HI
    JSR FORMATHEX16
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING

    LDA #SCREENCODE_SPACE
    JSR SCREENPUTCHAR

    JSR DAPPPRINTFLAGS
    RTS

; DAPPPRINTNAME - WRITES THE 15-CHAR NAME FIELD AT THE CURSOR, CONVERTING
; EXACTLY NAMELEN (APPBUF+APP_OFF_NAMELEN, 0-15) RAW PETSCII BYTES FROM APPBUF+APP_OFF_NAMEDATA VIA
; PETTOSCREEN, THEN SPACE-PADDING TO A FULL 15 CHARS. NEVER SCANS PAST
; NAMELEN BYTES OF THE PUBLIC NAME FIELD.
; CLOBBERS: A, X.
DAPPPRINTNAME:
    LDX #0
@LOOP:
    CPX APPBUF+APP_OFF_NAMELEN
    BCS @PAD
    LDA APPBUF+APP_OFF_NAMEDATA,X
    JSR PETTOSCREEN
    JSR SCREENPUTCHAR
    INX
    JMP @LOOP
@PAD:
    CPX #APP_NAME_WIDTH
    BCS @DONE
    LDA #SCREENCODE_SPACE
    JSR SCREENPUTCHAR
    INX
    JMP @PAD
@DONE:
    RTS

; DAPPPRINTRANGE - WRITES "LLLL-EEEE" AT THE CURSOR, WHERE LLLL IS LOADADDR
; (APPBUF+APP_OFF_LOADADDR/5) AND EEEE IS THE INCLUSIVE END (LOADADDR + SIZE - 1), COMPUTED
; WITH A CARRY-AWARE ADD/SUBTRACT. ON ZERO SIZE OR 16-BIT OVERFLOW, PRINTS
; "LLLL-????" INSTEAD OF WRAPPING (NEVER $FFFF VIA WRAPAROUND).
; CLOBBERS: A, X, Y.
DAPPPRINTRANGE:
    LDX APPBUF+APP_OFF_LOADADDR
    LDY APPBUF+APP_OFF_LOADADDR+1
    JSR FORMATHEX16
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING

    LDA #SCREENCODE_DASH
    JSR SCREENPUTCHAR

    CLC
    LDA APPBUF+APP_OFF_LOADADDR
    ADC APPBUF+APP_OFF_SIZE
    STA APPENDLO
    LDA APPBUF+APP_OFF_LOADADDR+1
    ADC APPBUF+APP_OFF_SIZE+1
    STA APPENDHI
    BCS @BAD            ; SUM >= $10000: OVERFLOW

    LDA APPBUF+APP_OFF_SIZE
    ORA APPBUF+APP_OFF_SIZE+1
    BEQ @BAD            ; SIZE == 0: NO VALID END

    SEC
    LDA APPENDLO
    SBC #1
    STA APPENDLO
    LDA APPENDHI
    SBC #0
    STA APPENDHI

    LDX APPENDLO
    LDY APPENDHI
    JSR FORMATHEX16
    LDA #SCREEN_COLS
    LDX #<FMTBUF
    LDY #>FMTBUF
    JSR SCREENPUTSTRING
    RTS

@BAD:
    LDA #SCREEN_COLS
    LDX #<APPRANGEBADSTR
    LDY #>APPRANGEBADSTR
    JSR SCREENPUTSTRING
    RTS

; DAPPPRINTFLAGS - WRITES THE 4-CHAR U/R/V/S FIELD AT THE CURSOR FROM THE
; RAW PUBLIC FLAGS BYTE (APPBUF+APP_OFF_FLAGS). EACH BIT PRINTS ITS LETTER IF SET, '-'
; OTHERWISE -- NO ROW HIGHLIGHT, NO INFERENCE BEYOND THE RAW BITS.
; CLOBBERS: A.
DAPPPRINTFLAGS:
    LDA APPBUF+APP_OFF_FLAGS
    PHA
    AND #APP_FLAG_USED
    BEQ DAPPFU_OFF
    LDA #$15                    ; 'U'
    JMP DAPPFU_PRINT
DAPPFU_OFF:
    LDA #SCREENCODE_DASH
DAPPFU_PRINT:
    JSR SCREENPUTCHAR

    PLA
    PHA
    AND #APP_FLAG_RUNNING
    BEQ DAPPFR_OFF
    LDA #$12                    ; 'R'
    JMP DAPPFR_PRINT
DAPPFR_OFF:
    LDA #$2D
DAPPFR_PRINT:
    JSR SCREENPUTCHAR

    PLA
    PHA
    AND #APP_FLAG_REU
    BEQ DAPPFV_OFF
    LDA #$16                    ; 'V'
    JMP DAPPFV_PRINT
DAPPFV_OFF:
    LDA #$2D
DAPPFV_PRINT:
    JSR SCREENPUTCHAR

    PLA
    AND #APP_FLAG_STACK
    BEQ DAPPFS_OFF
    LDA #$13                    ; 'S'
    JMP DAPPFS_PRINT
DAPPFS_OFF:
    LDA #$2D
DAPPFS_PRINT:
    JSR SCREENPUTCHAR
    RTS
